public static int squarePermutations(int[] A) {
    if (A.length == 0) {
        return 0;
    }

    int n = A.length;
    int[][] dp = new int[n][1 << n];
    dp[0][1 << 0] = 1;

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < 1 << n; j++) {
            for (int k = 0; k < n; k++) {
                if ((j & (1 << k)) != 0) {
                    int sum = A[k] + A[i];
                    if (isPerfectSquare(sum)) {
                        dp[i][j | (1 << i)] += dp[k][j];
                    }
                }
            }
        }
    }

    int result = 0;
    for (int i = 0; i < 1 << n; i++) {
        result += dp[n - 1][i];
    }

    return result;
}

public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int maxArea = 0;
    Stack<Integer> stack = new Stack<>();

    for (int i = 0; i <= n; i++) {
        while (!stack.isEmpty() && (i == n || heights[stack.peek()] > heights[i])) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0;
    boolean up = true;
    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];
        if (up) {
            if (col == n - 1) {
                row++;
                up = !up;
            } else if (row == 0) {
                col++;
                up = !up;
            } else {
                row--;
                col++;
            }
        } else {
            if (row == m - 1) {
                col++;
                up = !up;
            } else if (col == 0) {
                row++;
                up = !up;
            } else {
                row++;
                col--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            int minIndex = i + 1;
            for (int j = i + 2; j < digits.length; j++) {
                if (digits[j] > digits[i] && digits[j] <= digits[minIndex]) {
                    minIndex = j;
                }
            }
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;
            Arrays.sort(digits, i + 1, digits.length);
            break;
        }
    }
    long result = Long.parseLong(new String(digits));
    if (result > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) result > n ? (int) result : -1;
}

